import type { Metadata } from 'next'
import { site } from './site'

// Per-page metadata: title, description, canonical URL and share cards.
// The share image is generated by app/opengraph-image.tsx. Pages that set
// their own openGraph lose the inherited image, so it is attached explicitly.
const shareImage = {
  url: '/opengraph-image',
  width: 1200,
  height: 630,
  alt: 'AureonCare: EHR, scheduling and billing software for clinics',
}

export function pageMetadata({
  title,
  description,
  path,
  noindex = false,
}: {
  title: string
  description: string
  path: string
  noindex?: boolean
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { type: 'website', siteName: site.name, locale: 'en_US', url: path, title, description, images: [shareImage] },
    twitter: { card: 'summary_large_image', site: '@aureoncare', title, description, images: [shareImage.url] },
    ...(noindex && { robots: { index: false, follow: true } }),
  }
}
